         lfsm_vec[15] <= lfsm_vec[16] ^ edt_channels_in[4];
         lfsm_vec[16] <= lfsm_vec[17];
         lfsm_vec[17] <= lfsm_vec[18] ^ edt_channels_in[2];
         lfsm_vec[18] <= lfsm_vec[19];
         lfsm_vec[19] <= lfsm_vec[20] ^ edt_channels_in[0];
         lfsm_vec[20] <= from_previous_segment;
      end
   end

   assign to_previous_segment = lfsm_vec[ 0];
   assign to_next_segment     = lfsm_vec[10];

   always @(negedge edt_clock)
   begin : lockup_cells
      lfsm_vec_lockup <= lfsm_vec;
   end

   assign lfsm_vec_lockup_c = lfsm_vec_lockup & {21{scan_en}};

   always @(lfsm_vec_lockup_c)
   begin : phase_shifter
      edt_scan_in[  0] = lfsm_vec_lockup_c[ 4] ^ lfsm_vec_lockup_c[17] ^ lfsm_vec_lockup_c[18];
