   reg    [ 16:0] lfsm_vec;
   reg    [ 16:0] lfsm_vec_lockup;
   wire   [ 16:0] lfsm_vec_lockup_c;

   // synopsys sync_set_reset edt_update
   always @(posedge edt_clock)
   begin : lfsm
      if (edt_update == 1'b1) begin
         lfsm_vec <= 17'b00000000000000000;
