module processor_core_logic_test_tessent_edt_INT_EDT_decompressor_segment_18 (
   input  wire         edt_clock,
   input  wire         edt_update,
   input  wire         scan_en,
   input  wire [  6:0] edt_channels_in,
   output reg  [148:0] edt_scan_in,
   input  wire         from_previous_segment,
   output wire         to_previous_segment,
   input  wire         from_next_segment,
   output wire         to_next_segment
);
   reg    [ 20:0] lfsm_vec;
   reg    [ 20:0] lfsm_vec_lockup;
   wire   [ 20:0] lfsm_vec_lockup_c;

   // synopsys sync_set_reset edt_update
   always @(posedge edt_clock)
   begin : lfsm
      if (edt_update == 1'b1) begin
         lfsm_vec <= 21'b000000000000000000000;
      end
      else begin
         lfsm_vec[ 0] <= lfsm_vec[ 1];
         lfsm_vec[ 1] <= lfsm_vec[ 2];
         lfsm_vec[ 2] <= lfsm_vec[ 3] ^ edt_channels_in[2];
         lfsm_vec[ 3] <= lfsm_vec[ 4];
         lfsm_vec[ 4] <= lfsm_vec[ 5] ^ edt_channels_in[0];
         lfsm_vec[ 5] <= lfsm_vec[ 6];
         lfsm_vec[ 6] <= lfsm_vec[ 7] ^ edt_channels_in[5];
         lfsm_vec[ 7] <= lfsm_vec[ 8];
         lfsm_vec[ 8] <= lfsm_vec[ 9] ^ edt_channels_in[3];
         lfsm_vec[ 9] <= from_next_segment;
         lfsm_vec[10] <= lfsm_vec[11];
         lfsm_vec[11] <= lfsm_vec[12];
         lfsm_vec[12] <= lfsm_vec[13];
         lfsm_vec[13] <= lfsm_vec[14];
         lfsm_vec[14] <= lfsm_vec[15] ^ edt_channels_in[1];
         lfsm_vec[15] <= lfsm_vec[16];
         lfsm_vec[16] <= lfsm_vec[17] ^ edt_channels_in[6];
         lfsm_vec[17] <= lfsm_vec[18];
         lfsm_vec[18] <= lfsm_vec[19] ^ edt_channels_in[4];
         lfsm_vec[19] <= lfsm_vec[20] ^ lfsm_vec[ 2];
         lfsm_vec[20] <= from_previous_segment;
      end
   end

   assign to_previous_segment = lfsm_vec[ 0];
   assign to_next_segment     = lfsm_vec[10];

   always @(negedge edt_clock)
   begin : lockup_cells
      lfsm_vec_lockup <= lfsm_vec;
   end

   assign lfsm_vec_lockup_c = lfsm_vec_lockup & {21{scan_en}};

